BEGIN;
insert into public.ta_lessons(course_slug,lesson_no,title_pl,material) values
('garncarz-tradycja',0,'1. Od gliny do ceramiki: etapy przemiany materiału','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Co robi garncarz","text":"Garncarz projektuje i formuje naczynia z odpowiednio dobranej masy ceramicznej, kontroluje suszenie, wypał i ewentualne szkliwienie. Świeża glina jest plastyczna, wysuszony wyrób (greenware) jest kruchy, a po właściwym wypale zachodzą zmiany strukturalne, których nie cofnie proste dodanie wody. To nie jest jeden nieprzerwany etap pracy na kole."},{"heading":"Cztery stany, cztery decyzje","text":"Masa plastyczna nadaje się do kształtowania. W stanie skórzastej twardości (leather-hard) można w zależności od wyrobu dopracować detal; całkowicie suche greenware trzeba chronić przed uszkodzeniem. Biskwit, czyli wyrób po pierwszym wypale, może przyjmować szkliwo. Wyrób po docelowym wypale ma inne parametry niż biskwit."},{"heading":"Co decyduje o zastosowaniu","text":"Miska dekoracyjna, donica i kubek do napojów wymagają innych właściwości. O użytkowości decydują: nasiąkliwość, szczelność, zachowanie szkliwa, zgodność składników z kontaktem z żywnością, trwałość i wykonanie. Sam połysk szkliwa nie jest dowodem bezpieczeństwa naczynia."},{"heading":"Przypadek z pracowni","text":"Ktoś uformował kubek, wysuszył go na parapecie i od razu chce nalewać gorącą herbatę. Wysuszenie nie zamieniło gliny w wypaloną ceramikę. Przed użytkowaniem trzeba przejść właściwy proces i udokumentować przydatność wyrobu do danego celu."},{"heading":"Ćwiczenie początkującego","text":"Narysuj oś procesu: masa → formowanie → suszenie → pierwszy wypał → szkliwienie (jeżeli przewidziano) → wypał końcowy → kontrola. Przy każdym etapie wpisz: co zmienia się w materiale, jaki defekt można zauważyć i czego jeszcze nie wolno robić z wyrobem."}],"illustration":"garncarz-etapy","references":[{"label":"Źródło wiedzy technicznej","url":"https://openlearning.aalto.fi/course/view.php?id=110&section=13"}],"learning":{"intro":"Garncarz projektuje i formuje naczynia z odpowiednio dobranej masy ceramicznej, kontroluje suszenie, wypał i ewentualne szkliwienie. Świeża glina jest plastyczna, wysuszony wyrób (greenware) jest kruchy, a po właściwym wypale zachodzą zmiany strukturalne, których nie cofnie proste dodanie wody. To nie jest jeden nieprzerwany etap pracy na kole.","situation":"Ktoś uformował kubek, wysuszył go na parapecie i od razu chce nalewać gorącą herbatę. Wysuszenie nie zamieniło gliny w wypaloną ceramikę. Przed użytkowaniem trzeba przejść właściwy proces i udokumentować przydatność wyrobu do danego celu.","question":"Co odróżnia wysuszone greenware od ceramiki po odpowiednim wypale?","options":["Greenware jest zawsze wodoodporne po wyschnięciu.","W wypale zachodzą przemiany struktury; samo suszenie ich nie zastępuje.","Samo wysuszenie automatycznie zapewnia szkliwo.","Przy greenware nie występuje skurcz ani kruche pękanie."],"correct":1,"example":"W wypale zachodzą przemiany struktury; samo suszenie ich nie zastępuje.","explanation":"Proces wypalania prowadzi do zmian trwałych w strukturze ceramicznej; wysuszone greenware pozostaje kruche i podatne na działanie wody.","feedback":["Sprawdź mechanizm przedstawiony w lekcji. Proces wypalania prowadzi do zmian trwałych w strukturze ceramicznej; wysuszone greenware pozostaje kruche i podatne na działanie wody.","Tak. Proces wypalania prowadzi do zmian trwałych w strukturze ceramicznej; wysuszone greenware pozostaje kruche i podatne na działanie wody.","Sprawdź mechanizm przedstawiony w lekcji. Proces wypalania prowadzi do zmian trwałych w strukturze ceramicznej; wysuszone greenware pozostaje kruche i podatne na działanie wody.","Sprawdź mechanizm przedstawiony w lekcji. Proces wypalania prowadzi do zmian trwałych w strukturze ceramicznej; wysuszone greenware pozostaje kruche i podatne na działanie wody."],"task":"Narysuj oś procesu: masa → formowanie → suszenie → pierwszy wypał → szkliwienie (jeżeli przewidziano) → wypał końcowy → kontrola. Przy każdym etapie wpisz: co zmienia się w materiale, jaki defekt można zauważyć i czego jeszcze nie wolno robić z wyrobem."}}'::jsonb),
('garncarz-tradycja',1,'2. Materiałoznawstwo: glina, szamot, masy i nasiąkliwość','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Nie każda glina jest tą samą masą","text":"Masa ceramiczna może zawierać różne minerały ilaste, składniki nieplastyczne i dodatki. Gliny do ceramiki porowatej, kamionki czy porcelany różnią się zachowaniem w obróbce i podczas wypału. Dobór musi odpowiadać temperaturze dojrzewania masy oraz przewidywanemu zastosowaniu, a nie jedynie kolorowi w stanie surowym."},{"heading":"Plastyczność i szamot","text":"Plastyczność ułatwia formowanie i utrzymanie kształtu, ale bardzo plastyczna masa może wykazywać znaczący skurcz. Szamot to wypalony i rozdrobniony materiał ceramiczny stosowany jako domieszka w wybranych masach. Może wpływać na zachowanie podczas suszenia i fakturę, lecz nie rozwiązuje automatycznie wszystkich wad."},{"heading":"Nasiąkliwość i dojrzałość wypału","text":"Po wypale porowatość i nasiąkliwość zależą od składu oraz historii wypału. Masy porowate i bardziej spieczone zachowują się inaczej. Nie ma jednego zakresu temperatur pasującego do każdej gliny; producent określa dopuszczalny zakres. Sam kolor ciemny lub jasny nie wystarcza do rozpoznania właściwości."},{"heading":"Przykład zamiany masy","text":"Masz szkliwo przeznaczone do określonego zakresu wypału i producent zamienia masę na inną, dojrzewającą w innej temperaturze. Użycie starego programu bez sprawdzenia kompatybilności może skończyć się odkształceniem, nieprawidłowym spiekiem lub wadą szkliwa."},{"heading":"Karta materiałowa","text":"Zaprojektuj zestawienie dla trzech mas: przewidywany wyrób, plastyczność, zawartość szamotu, skurcz z karty technicznej, zakres wypału, sposób kontroli i ograniczenia. Dodaj pole ''dane niepotwierdzone'', aby nie zastępować badania intuicją."}],"illustration":"material-garncarz-tradycja","references":[{"label":"Źródło wiedzy technicznej","url":"https://openlearning.aalto.fi/course/view.php?id=110&section=13"}],"learning":{"intro":"Masa ceramiczna może zawierać różne minerały ilaste, składniki nieplastyczne i dodatki. Gliny do ceramiki porowatej, kamionki czy porcelany różnią się zachowaniem w obróbce i podczas wypału. Dobór musi odpowiadać temperaturze dojrzewania masy oraz przewidywanemu zastosowaniu, a nie jedynie kolorowi w stanie surowym.","situation":"Masz szkliwo przeznaczone do określonego zakresu wypału i producent zamienia masę na inną, dojrzewającą w innej temperaturze. Użycie starego programu bez sprawdzenia kompatybilności może skończyć się odkształceniem, nieprawidłowym spiekiem lub wadą szkliwa.","question":"Dlaczego nie należy stosować jednego programu wypału do dowolnych dwóch mas ceramicznych?","options":["Ponieważ kolor surowej masy wyznacza automatycznie idealną temperaturę.","Ponieważ każdy dodatek szamotu usuwa potrzebę kontroli wypału.","Ponieważ program wypału służy tylko do suszenia.","Ponieważ skład i zakres dojrzewania masy mogą się istotnie różnić."],"correct":3,"example":"Ponieważ skład i zakres dojrzewania masy mogą się istotnie różnić.","explanation":"Masy ceramiczne różnią się składem, skurczem i zakresem spiekania; program ma odpowiadać producentowi i wyrobowi.","feedback":["Sprawdź mechanizm przedstawiony w lekcji. Masy ceramiczne różnią się składem, skurczem i zakresem spiekania; program ma odpowiadać producentowi i wyrobowi.","Sprawdź mechanizm przedstawiony w lekcji. Masy ceramiczne różnią się składem, skurczem i zakresem spiekania; program ma odpowiadać producentowi i wyrobowi.","Sprawdź mechanizm przedstawiony w lekcji. Masy ceramiczne różnią się składem, skurczem i zakresem spiekania; program ma odpowiadać producentowi i wyrobowi.","Tak. Masy ceramiczne różnią się składem, skurczem i zakresem spiekania; program ma odpowiadać producentowi i wyrobowi."],"task":"Zaprojektuj zestawienie dla trzech mas: przewidywany wyrób, plastyczność, zawartość szamotu, skurcz z karty technicznej, zakres wypału, sposób kontroli i ograniczenia. Dodaj pole ''dane niepotwierdzone'', aby nie zastępować badania intuicją."}}'::jsonb),
('garncarz-tradycja',2,'3. Pracownia i narzędzia: koło, drut, oczko, nerka','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Nie zaczynamy od uruchamiania pieca","text":"W pracowni oddziela się strefę przygotowania masy, formowania, suszenia, szkliwienia i pieca. Mieszanie suchego proszku czy zamiatanie na sucho może zwiększać stężenie pyłu zawierającego krzemionkę. Potrzebne są odpowiednie rozwiązania organizacyjne, czyszczenie na mokro i kontrola pylenia zgodnie z oceną ryzyka."},{"heading":"Poznaj narzędzia według działania","text":"Koło garncarskie obraca materiał wokół osi i pomaga tworzyć formy osiowo symetryczne. Drut służy do oddzielania wyrobu od podłoża; oczko i narzędzia pętlowe usuwają masę podczas toczenia wykończeniowego. Nerka garncarska wygładza i kształtuje ściany. Gąbka pozwala kontrolować powierzchnię i ilość wody."},{"heading":"Co pokazuje centrum obrotu","text":"Gdy masa nie jest wycentrowana, podczas obrotu jej kształt zmienia się względem nieruchomego punktu obserwacji. Utrudnia to uzyskanie równomiernej grubości ściany. Samo zwiększenie prędkości nie usuwa błędu centrowania; ważna jest stabilność i odpowiednia technika pracy."},{"heading":"Kontrole przed praktyką","text":"Weryfikuj osłony i zasilanie urządzeń, suchą strefę elektroniki, stabilność podstawy, czyste narzędzia, brak pęknięć, włosów i luźnej odzieży przy ruchu obrotowym. Z piecem i techniką elektryczną pracuje wyłącznie osoba przeszkolona."},{"heading":"Ćwiczenie na ilustracji","text":"Narysuj rzut warsztatu z drogą materiału i pięcioma narzędziami. Dla każdego wpisz nazwę, rezultat, potencjalny błąd oraz bezpieczną metodę przechowywania. Wyjaśnij różnicę między centrowaniem, formowaniem a wykończeniem wyrobu."}],"illustration":"technique-garncarz-tradycja","references":[{"label":"Źródło wiedzy technicznej","url":"https://www.hse.gov.uk/coshh/essentials/direct-advice/ceramics-silica.htm"}],"learning":{"intro":"W pracowni oddziela się strefę przygotowania masy, formowania, suszenia, szkliwienia i pieca. Mieszanie suchego proszku czy zamiatanie na sucho może zwiększać stężenie pyłu zawierającego krzemionkę. Potrzebne są odpowiednie rozwiązania organizacyjne, czyszczenie na mokro i kontrola pylenia zgodnie z oceną ryzyka.","situation":"Weryfikuj osłony i zasilanie urządzeń, suchą strefę elektroniki, stabilność podstawy, czyste narzędzia, brak pęknięć, włosów i luźnej odzieży przy ruchu obrotowym. Z piecem i techniką elektryczną pracuje wyłącznie osoba przeszkolona.","question":"Do czego służy nerka garncarska podczas pracy na kole?","options":["Do zmiany programu temperatury pieca.","Do wykonywania testów chemicznych szkliwa.","Do wygładzania i kształtowania powierzchni gliny.","Do obniżania zawartości pyłu w wentylacji."],"correct":2,"example":"Do wygładzania i kształtowania powierzchni gliny.","explanation":"Nerka garncarska (rib) pomaga kontrolować kształt i wygładzać powierzchnię plastycznej masy, nie służy do sterowania piecem.","feedback":["Sprawdź mechanizm przedstawiony w lekcji. Nerka garncarska (rib) pomaga kontrolować kształt i wygładzać powierzchnię plastycznej masy, nie służy do sterowania piecem.","Sprawdź mechanizm przedstawiony w lekcji. Nerka garncarska (rib) pomaga kontrolować kształt i wygładzać powierzchnię plastycznej masy, nie służy do sterowania piecem.","Tak. Nerka garncarska (rib) pomaga kontrolować kształt i wygładzać powierzchnię plastycznej masy, nie służy do sterowania piecem.","Sprawdź mechanizm przedstawiony w lekcji. Nerka garncarska (rib) pomaga kontrolować kształt i wygładzać powierzchnię plastycznej masy, nie służy do sterowania piecem."],"task":"Narysuj rzut warsztatu z drogą materiału i pięcioma narzędziami. Dla każdego wpisz nazwę, rezultat, potencjalny błąd oraz bezpieczną metodę przechowywania. Wyjaśnij różnicę między centrowaniem, formowaniem a wykończeniem wyrobu."}}'::jsonb),
('garncarz-tradycja',3,'4. Projekt kubka: skurcz, grubość i dokumentacja','{"module":1,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Najpierw wyznacz gotowy wymiar","text":"Wymiary w formie mokrej nie są wymiarami po wyschnięciu i wypale. Skurcz całkowity zależy od masy i procesu, dlatego zanim wykonasz seryjny wyrób, potrzebujesz próbek i karty materiału. Przekrój projektu powinien pokazywać wysokość, średnicę, grubość ściany, dno oraz sposób mocowania ucha."},{"heading":"Przykład rachunku","text":"Załóżmy wyłącznie do ćwiczenia, że skurcz liniowy od wymiaru przed suszeniem do po wypale wynosi 12%. Aby uzyskać po wypale wysokość 100 mm, potrzebny wymiar początkowy to 100/(1−0,12)=113,64 mm. Nie wolno dodawać tylko 12 mm do wymiaru gotowego: procent liczy się od wymiaru początkowego."},{"heading":"Dobór kształtu do funkcji","text":"Kubek przeznaczony do picia wymaga m.in. stabilnej podstawy, wygodnej krawędzi, odpowiedniego ucha i trwałej powierzchni. Grubość ścianki wpływa na masę i proces suszenia. Przy projekcie ważne jest również przewidzenie połączenia ucha i sposób uniknięcia lokalnego naprężenia podczas schnięcia."},{"heading":"Przykład błędu","text":"Projektant przygotował kubek dokładnie 100 mm przed wypałem, mimo rzeczywistego skurczu 12%. Po wypale osiągnął około 88 mm. Błąd nie polega na ''źle ustawionym linijce'', tylko na pominięciu skurczu we wzorze i braku próbki."},{"heading":"Zadanie z obliczeniem","text":"Przyjmij skurcz 10% i docelową średnicę zewnętrzną 90 mm. Oblicz średnicę początkową: 90/0,90=100 mm. Zrób tabelę dla trzech wymiarów i zanotuj, że są to wartości planistyczne, które trzeba potwierdzić na próbach danej masy."}],"illustration":"garncarz-skurcz","references":[{"label":"Źródło wiedzy technicznej","url":"https://openlearning.aalto.fi/course/view.php?id=110&section=13"}],"learning":{"intro":"Wymiary w formie mokrej nie są wymiarami po wyschnięciu i wypale. Skurcz całkowity zależy od masy i procesu, dlatego zanim wykonasz seryjny wyrób, potrzebujesz próbek i karty materiału. Przekrój projektu powinien pokazywać wysokość, średnicę, grubość ściany, dno oraz sposób mocowania ucha.","situation":"Projektant przygotował kubek dokładnie 100 mm przed wypałem, mimo rzeczywistego skurczu 12%. Po wypale osiągnął około 88 mm. Błąd nie polega na ''źle ustawionym linijce'', tylko na pominięciu skurczu we wzorze i braku próbki.","question":"Chcesz uzyskać kubek o wysokości 100 mm przy planistycznym skurczu liniowym 12%. Jaki początkowy wymiar wynika z modelu?","options":["88 mm.","112 mm.","100 mm.","Około 113,6 mm."],"correct":3,"example":"Około 113,6 mm.","explanation":"Wymiar końcowy = początkowy × 0,88, zatem początkowy = 100/0,88 ≈ 113,6 mm.","feedback":["Sprawdź mechanizm przedstawiony w lekcji. Wymiar końcowy = początkowy × 0,88, zatem początkowy = 100/0,88 ≈ 113,6 mm.","Sprawdź mechanizm przedstawiony w lekcji. Wymiar końcowy = początkowy × 0,88, zatem początkowy = 100/0,88 ≈ 113,6 mm.","Sprawdź mechanizm przedstawiony w lekcji. Wymiar końcowy = początkowy × 0,88, zatem początkowy = 100/0,88 ≈ 113,6 mm.","Tak. Wymiar końcowy = początkowy × 0,88, zatem początkowy = 100/0,88 ≈ 113,6 mm."],"task":"Przyjmij skurcz 10% i docelową średnicę zewnętrzną 90 mm. Oblicz średnicę początkową: 90/0,90=100 mm. Zrób tabelę dla trzech wymiarów i zanotuj, że są to wartości planistyczne, które trzeba potwierdzić na próbach danej masy."}}'::jsonb),
('garncarz-tradycja',4,'5. Przygotowanie masy i formowanie: płaty, wałki i koło','{"module":2,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Czym jest przygotowanie masy","text":"Przed formowaniem trzeba upewnić się, że glina ma odpowiednią konsystencję i jest jednorodna. Nierównomierna zawartość wody może prowadzić do różnych odkształceń. Pojęcia takie jak odpowietrzanie i wyrabianie masy mają znaczenie, ale nie zastępują kontroli wilgotności, rodzaju masy i jej stanu."},{"heading":"Trzy techniki, różne możliwości","text":"Lepienie z wałeczków (coiling) pozwala budować ścianki z kolejnych pasm. Technika płatów (slab building) opiera się na rozwałkowanych elementach łączonych w określonym stanie wilgotności. Toczenie na kole umożliwia osiową symetrię, ale wymaga centrowania i stałej kontroli grubości. Dla każdego projektu wybierz technikę z uwzględnieniem geometrii."},{"heading":"Dlaczego łączenia mogą pękać","text":"Łączone elementy o różnym stopniu wyschnięcia kurczą się w różnym tempie. Jeśli ucho jest mocowane do znacznie bardziej suchego korpusu albo odwrotnie, w miejscu połączenia mogą powstać naprężenia i pęknięcia. Nie zastępuj prawidłowego połączenia nakładaniem grubej warstwy szkliwa."},{"heading":"Przykład projektu","text":"Zlecenie to prostokątna osłona na roślinę o prostych ścianach. Technika płatów może być bardziej uzasadniona niż koło, ponieważ nie wymaga obracania kształtu osiowego. Przy projektowaniu uwzględnij suszenie naroży i miejsce styku płatów."},{"heading":"Ćwiczenie projektowe","text":"Dla kubka, talerza i prostokątnego pojemnika wybierz spośród wałków, płatów lub koła technikę i uzasadnij ją. Narysuj przekrój i dwa punkty możliwego pęknięcia dla każdego przedmiotu."}],"illustration":"technique-garncarz-tradycja","references":[{"label":"Źródło wiedzy technicznej","url":"https://www.digitalfire.com/glossary/drying%2Bcrack"}],"learning":{"intro":"Przed formowaniem trzeba upewnić się, że glina ma odpowiednią konsystencję i jest jednorodna. Nierównomierna zawartość wody może prowadzić do różnych odkształceń. Pojęcia takie jak odpowietrzanie i wyrabianie masy mają znaczenie, ale nie zastępują kontroli wilgotności, rodzaju masy i jej stanu.","situation":"Zlecenie to prostokątna osłona na roślinę o prostych ścianach. Technika płatów może być bardziej uzasadniona niż koło, ponieważ nie wymaga obracania kształtu osiowego. Przy projektowaniu uwzględnij suszenie naroży i miejsce styku płatów.","question":"Dlaczego ucho z bardzo mokrej masy może pękać po dołączeniu do znacznie suchszego kubka?","options":["Elementy mogą kurczyć się inaczej, tworząc naprężenia w połączeniu.","Ponieważ każde ucho musi być wypalane osobno od kubka.","Ponieważ grubość szkliwa zawsze eliminuje różnice wilgotności.","Ponieważ koło automatycznie wyrównuje wilgotność dowolnego połączenia."],"correct":0,"example":"Elementy mogą kurczyć się inaczej, tworząc naprężenia w połączeniu.","explanation":"Różna zawartość wody i etap schnięcia powodują nierównomierny skurcz oraz ryzyko pękania w strefie łączenia.","feedback":["Tak. Różna zawartość wody i etap schnięcia powodują nierównomierny skurcz oraz ryzyko pękania w strefie łączenia.","Sprawdź mechanizm przedstawiony w lekcji. Różna zawartość wody i etap schnięcia powodują nierównomierny skurcz oraz ryzyko pękania w strefie łączenia.","Sprawdź mechanizm przedstawiony w lekcji. Różna zawartość wody i etap schnięcia powodują nierównomierny skurcz oraz ryzyko pękania w strefie łączenia.","Sprawdź mechanizm przedstawiony w lekcji. Różna zawartość wody i etap schnięcia powodują nierównomierny skurcz oraz ryzyko pękania w strefie łączenia."],"task":"Dla kubka, talerza i prostokątnego pojemnika wybierz spośród wałków, płatów lub koła technikę i uzasadnij ją. Narysuj przekrój i dwa punkty możliwego pęknięcia dla każdego przedmiotu."}}'::jsonb),
('garncarz-tradycja',5,'6. Suszenie greenware: skąd biorą się pęknięcia i wypaczenia','{"module":2,"curriculum_revision":3,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","sections":[{"heading":"Suszenie nie jest równoznaczne z wypałem","text":"Podczas suszenia z masy odparowuje woda, a element może zmniejszać wymiary. Świeżo uformowane naczynie ma różną grubość, więc jego części mogą schnąć w różnym tempie. Szybsza utrata wody przez cienki brzeg niż przez grube dno sprzyja powstawaniu naprężeń."},{"heading":"Co jest oznaką problemu","text":"Pęknięcie przy uchu może sugerować różnicę wilgotności elementów w chwili połączenia, a rysa przy grubym dnie — nierównomierne wysychanie. Krzywizna dużego płata może wynikać z różnic skurczu i nieprawidłowego podparcia. Sama lokalizacja nie stanowi jeszcze pewnej diagnozy."},{"heading":"Jak dokumentować proces","text":"Zapisuj masę ceramiczną, wymiary, sposób formowania, warunki suszenia i dostrzeżone defekty. Unikaj gwałtownego suszenia na gorącym grzejniku bez uzasadnionego planu. Przed wypałem stan wysuszenia musi być odpowiedni do bezpieczeństwa procesu; wilgotny wyrób może pękać pod wpływem pary."},{"heading":"Przykład z pomiarem","text":"Płytka przed suszeniem ma 200 mm długości, po wyschnięciu 188 mm. Skurcz na tym etapie to (200−188)/200×100%=6%. Wynik nie jest jeszcze całkowitym skurczem do końca wypału. Właśnie dlatego trzeba przechowywać oba wymiary w karcie próbki."},{"heading":"Zadanie kontrolne","text":"Ułóż kartę pięciu próbek z pomiarami przed suszeniem i po nim, policz skurcz procentowy oraz zanotuj miejsca pęknięć. Wybierz najbardziej prawdopodobne przyczyny i proponowane zmiany w następnym doświadczeniu."}],"illustration":"diagnosis-garncarz-tradycja","references":[{"label":"Źródło wiedzy technicznej","url":"https://www.digitalfire.com/glossary/drying%2Bcrack"}],"learning":{"intro":"Podczas suszenia z masy odparowuje woda, a element może zmniejszać wymiary. Świeżo uformowane naczynie ma różną grubość, więc jego części mogą schnąć w różnym tempie. Szybsza utrata wody przez cienki brzeg niż przez grube dno sprzyja powstawaniu naprężeń.","situation":"Płytka przed suszeniem ma 200 mm długości, po wyschnięciu 188 mm. Skurcz na tym etapie to (200−188)/200×100%=6%. Wynik nie jest jeszcze całkowitym skurczem do końca wypału. Właśnie dlatego trzeba przechowywać oba wymiary w karcie próbki.","question":"Płytka ma 200 mm długości w stanie mokrym, a 188 mm po suszeniu. Jaki skurcz liniowy nastąpił na tym etapie?","options":["12%.","Około 6%.","Około 0,6%.","Wynik jest zerowy, ponieważ płytka nie została wypalona."],"correct":1,"example":"Około 6%.","explanation":"(200−188)/200×100%=6%. Suszenie powoduje skurcz przed wypałem.","feedback":["Sprawdź mechanizm przedstawiony w lekcji. (200−188)/200×100%=6%. Suszenie powoduje skurcz przed wypałem.","Tak. (200−188)/200×100%=6%. Suszenie powoduje skurcz przed wypałem.","Sprawdź mechanizm przedstawiony w lekcji. (200−188)/200×100%=6%. Suszenie powoduje skurcz przed wypałem.","Sprawdź mechanizm przedstawiony w lekcji. (200−188)/200×100%=6%. Suszenie powoduje skurcz przed wypałem."],"task":"Ułóż kartę pięciu próbek z pomiarami przed suszeniem i po nim, policz skurcz procentowy oraz zanotuj miejsca pęknięć. Wybierz najbardziej prawdopodobne przyczyny i proponowane zmiany w następnym doświadczeniu."}}'::jsonb),
('garncarz-tradycja',6,'7. Pierwszy wypał (biskwit): cele, etapy i typowe błędy','{"module":2,"editorial_status":"review_needed","curriculum_revision":3,"lesson_kind":"technical_curriculum","sections":[{"heading":"Po co wykonuje się pierwszy wypał","text":"Biskwit to naczynie po pierwszym wypale, często nadal porowate na tyle, aby przyjąć szkliwo w przewidzianej technologii. Wypał zmienia strukturę masy i usuwa część składników lotnych; nie zastępuje prawidłowego suszenia przed włożeniem do pieca. Konkretny program zależy od masy i urządzenia."},{"heading":"Mokra masa w piecu jest zagrożeniem","text":"Jeżeli wewnątrz wyrobu pozostaje wilgoć, para powstająca podczas ogrzewania może doprowadzić do pęknięć lub gwałtownego rozpadu elementu. Nie można uznać dużej rzeźby za suchą wyłącznie na podstawie powierzchni. Grube miejsca i zamknięte objętości wymagają szczególnej oceny stanu przed wypałem."},{"heading":"Wykres czasu i temperatury","text":"Program wypału to nie tylko wartość końcowej temperatury. Ma etapy wzrostu, ewentualne przetrzymanie i chłodzenie. Nie należy podawać jednego uniwersalnego programu wszystkim uczniom: trzeba czytać instrukcję pieca, kartę masy i uzasadnienie technologiczne zatwierdzone przez instruktora."},{"heading":"Przykład odbioru partii","text":"Trzy kubki z jednej partii są suche z zewnątrz; jeden ma bardzo grube dno. Bez potwierdzenia dostatecznego wyschnięcia dna nie należy wkładać go wraz z pozostałymi w zwykłym cyklu. W protokole zapisuje się decyzję o odłożeniu sztuki do dalszej kontroli."},{"heading":"Ćwiczenie dokumentacyjne","text":"Narysuj prosty wykres: temperatura na osi pionowej, czas na poziomej. Zaznacz etapy programu bez wprowadzania konkretnych parametrów do rzeczywistego pieca. Przygotuj checklistę przyjęcia wyrobów do wypału: identyfikator, masa, grubość, stan wysuszenia, instrukcja, operator i decyzja."}],"illustration":"garncarz-etapy","references":[{"label":"Źródło wiedzy technicznej","url":"https://openlearning.aalto.fi/course/view.php?id=110&section=13"}],"learning":{"intro":"Biskwit to naczynie po pierwszym wypale, często nadal porowate na tyle, aby przyjąć szkliwo w przewidzianej technologii. Wypał zmienia strukturę masy i usuwa część składników lotnych; nie zastępuje prawidłowego suszenia przed włożeniem do pieca. Konkretny program zależy od masy i urządzenia.","situation":"Trzy kubki z jednej partii są suche z zewnątrz; jeden ma bardzo grube dno. Bez potwierdzenia dostatecznego wyschnięcia dna nie należy wkładać go wraz z pozostałymi w zwykłym cyklu. W protokole zapisuje się decyzję o odłożeniu sztuki do dalszej kontroli.","question":"Która sytuacja jest szczególnie ryzykowna przed pierwszym wypałem?","options":["Jednolita dokumentacja partii.","Sprawdzenie instrukcji masy i pieca.","Grube, wilgotne wnętrze wyrobu, choć powierzchnia wydaje się sucha.","Odkładanie niepewnej sztuki do dodatkowej kontroli."],"correct":2,"example":"Grube, wilgotne wnętrze wyrobu, choć powierzchnia wydaje się sucha.","explanation":"Para wytwarzana wewnątrz niedosuszonego wyrobu może powodować poważne pęknięcia lub rozpad podczas wypału.","feedback":["Nie. Para wytwarzana wewnątrz niedosuszonego wyrobu może powodować poważne pęknięcia lub rozpad podczas wypału.","Nie. Para wytwarzana wewnątrz niedosuszonego wyrobu może powodować poważne pęknięcia lub rozpad podczas wypału.","Tak. Para wytwarzana wewnątrz niedosuszonego wyrobu może powodować poważne pęknięcia lub rozpad podczas wypału.","Nie. Para wytwarzana wewnątrz niedosuszonego wyrobu może powodować poważne pęknięcia lub rozpad podczas wypału."],"task":"Narysuj prosty wykres: temperatura na osi pionowej, czas na poziomej. Zaznacz etapy programu bez wprowadzania konkretnych parametrów do rzeczywistego pieca. Przygotuj checklistę przyjęcia wyrobów do wypału: identyfikator, masa, grubość, stan wysuszenia, instrukcja, operator i decyzja."}}'::jsonb),
('garncarz-tradycja',7,'8. Szkliwo, angoba i powierzchnia: co daje każda warstwa','{"module":2,"editorial_status":"review_needed","curriculum_revision":3,"lesson_kind":"technical_curriculum","sections":[{"heading":"Nie myl szkliwa z angobą","text":"Szkliwo jest powłoką, która podczas właściwego wypału tworzy warstwę szklistą na powierzchni. Angoba to cienka warstwa materiału ceramicznego o składzie i zastosowaniu zależnym od technologii; może służyć zmianie barwy lub faktury. Farba dekoracyjna nie jest automatycznie szkliwem ani powłoką dopuszczoną do żywności."},{"heading":"Zgodność masy i szkliwa","text":"Szkliwo musi pasować do masy pod kątem właściwości termicznych i warunków wypału. Sam fakt, że produkt ma etykietę ''szkliwo przezroczyste'', nie gwarantuje przydatności do każdej gliny ani możliwości zastosowania na powierzchniach mających kontakt z jedzeniem."},{"heading":"Grubość i czystość podstawy","text":"Nierównomiernie nałożone szkliwo może zaciekać, gromadzić się lub tworzyć niepożądane defekty. W pracowni wykonuje się próby zestawu masa–szkliwo, dokumentuje produkt, dostawcę, sposób nakładania i wynik wypału. Warunki zależą od konkretnych receptur, nie od intuicyjnej zasady ''im więcej, tym lepiej''."},{"heading":"Przykład problemu","text":"Uczeń ma biskwit po wypale, ale wybiera szkliwo z innego systemu i nie sprawdza zakresu jego zastosowania. Po wypale powstają wady. Właściwa analiza zaczyna się od danych producenta, zgodności masy i szkliwa oraz historii zastosowanego programu."},{"heading":"Ćwiczenie bezpiecznej analizy","text":"Porównaj trzy etykiety hipotetycznych materiałów: szkliwo, angoba i farba dekoracyjna. Uzupełnij tabelę: skład/typ, etap nakładania, wymagana technologia, przeznaczenie, ograniczenia i wymagane testy. Rozdziel zastosowanie dekoracyjne od kontaktu z żywnością."}],"illustration":"garncarz-szkliwo","references":[{"label":"Źródło wiedzy technicznej","url":"https://www.digitalfire.com/glossary/glaze%2Bfit"}],"learning":{"intro":"Szkliwo jest powłoką, która podczas właściwego wypału tworzy warstwę szklistą na powierzchni. Angoba to cienka warstwa materiału ceramicznego o składzie i zastosowaniu zależnym od technologii; może służyć zmianie barwy lub faktury. Farba dekoracyjna nie jest automatycznie szkliwem ani powłoką dopuszczoną do żywności.","situation":"Uczeń ma biskwit po wypale, ale wybiera szkliwo z innego systemu i nie sprawdza zakresu jego zastosowania. Po wypale powstają wady. Właściwa analiza zaczyna się od danych producenta, zgodności masy i szkliwa oraz historii zastosowanego programu.","question":"Co jest najważniejszym kryterium przy doborze szkliwa do naczynia użytkowego?","options":["Wyłącznie podobny kolor surowego proszku.","Zgodność z masą i zakresem wypału oraz potwierdzona przydatność do kontaktu z żywnością.","Największa możliwa grubość każdej warstwy.","To, że szkliwo ma taką samą nazwę handlową jak glina."],"correct":1,"example":"Zgodność z masą i zakresem wypału oraz potwierdzona przydatność do kontaktu z żywnością.","explanation":"Właściwości szkliwa i masy oraz bezpieczeństwo zastosowania muszą być potwierdzone dla konkretnego układu, nie oceniane po kolorze.","feedback":["Nie. Właściwości szkliwa i masy oraz bezpieczeństwo zastosowania muszą być potwierdzone dla konkretnego układu, nie oceniane po kolorze.","Tak. Właściwości szkliwa i masy oraz bezpieczeństwo zastosowania muszą być potwierdzone dla konkretnego układu, nie oceniane po kolorze.","Nie. Właściwości szkliwa i masy oraz bezpieczeństwo zastosowania muszą być potwierdzone dla konkretnego układu, nie oceniane po kolorze.","Nie. Właściwości szkliwa i masy oraz bezpieczeństwo zastosowania muszą być potwierdzone dla konkretnego układu, nie oceniane po kolorze."],"task":"Porównaj trzy etykiety hipotetycznych materiałów: szkliwo, angoba i farba dekoracyjna. Uzupełnij tabelę: skład/typ, etap nakładania, wymagana technologia, przeznaczenie, ograniczenia i wymagane testy. Rozdziel zastosowanie dekoracyjne od kontaktu z żywnością."}}'::jsonb),
('garncarz-tradycja',8,'9. Piec ceramiczny i bezpieczeństwo: wentylacja, pył, temperatura','{"module":3,"editorial_status":"review_needed","curriculum_revision":3,"lesson_kind":"technical_curriculum","sections":[{"heading":"Dwa różne zagrożenia","text":"W pracowni występują co najmniej dwa niezależne rodzaje ryzyka: wdychanie drobnego pyłu zawierającego krystaliczną krzemionkę oraz praca z gorącym piecem, energią elektryczną lub gazem. Ochrona przed jednym zagrożeniem nie usuwa drugiego; potrzebny jest plan bezpieczeństwa oparty na rzeczywistym procesie."},{"heading":"Pył ceramiczny","text":"Suche zamiatanie, szlifowanie i dozowanie proszków może zwiększać narażenie. Procedura powinna ograniczać emisję u źródła, używać właściwej wentylacji i metod sprzątania na mokro, a wymagane środki ochrony dobierać po ocenie ryzyka. Kurs online nie upoważnia do samodzielnej pracy w zapylonym stanowisku."},{"heading":"Piec i przestrzeń wokół","text":"Piec musi mieć odpowiednie odstępy od materiałów palnych i elementów konstrukcyjnych, skuteczną wentylację oraz zabezpieczenia zgodne z instrukcją producenta. Nie należy składować kartonów lub drewna blisko jego powierzchni. Występują gorące powierzchnie i ryzyko pożaru, zwłaszcza przy wadliwym ustawieniu albo kontroli."},{"heading":"Przykład awarii organizacyjnej","text":"W pracowni piec stoi przy drewnianej zabudowie, a obok odmierza się suchą masę szkliwną bez kontroli pyłu. Nie wystarczy kupić rękawic żaroodpornych — trzeba oddzielnie rozwiązać układ przestrzeni, wentylację, pylenie i procedurę pracy."},{"heading":"Ćwiczenie BHP","text":"Narysuj plan warsztatu z kołem, strefą mokrą, składowaniem suchych surowców, miejscem odpylania, piecem i drogą ewakuacji. Dla każdej strefy zapisz zagrożenie, środek kontroli i odpowiedzialną osobę. Nie podawaj uniwersalnego odstępu pieca bez znajomości jego modelu."}],"illustration":"garncarz-bezpieczenstwo","references":[{"label":"Źródło wiedzy technicznej","url":"https://www.hse.gov.uk/non-metallic-minerals/kilns-in-schools.htm"}],"learning":{"intro":"W pracowni występują co najmniej dwa niezależne rodzaje ryzyka: wdychanie drobnego pyłu zawierającego krystaliczną krzemionkę oraz praca z gorącym piecem, energią elektryczną lub gazem. Ochrona przed jednym zagrożeniem nie usuwa drugiego; potrzebny jest plan bezpieczeństwa oparty na rzeczywistym procesie.","situation":"W pracowni piec stoi przy drewnianej zabudowie, a obok odmierza się suchą masę szkliwną bez kontroli pyłu. Nie wystarczy kupić rękawic żaroodpornych — trzeba oddzielnie rozwiązać układ przestrzeni, wentylację, pylenie i procedurę pracy.","question":"Dlaczego same rękawice termiczne nie rozwiązują problemu bezpieczeństwa pieca i glazury?","options":["Ponieważ ochronę przed pyłem, wentylację i odległości od materiałów palnych trzeba ocenić niezależnie.","Ponieważ piece ceramiczne nie wytwarzają ciepła zewnętrznego.","Ponieważ każda glina jest wolna od krzemionki.","Ponieważ zwiększenie liczby rękawic zastępuje system wentylacji."],"correct":0,"example":"Ponieważ ochronę przed pyłem, wentylację i odległości od materiałów palnych trzeba ocenić niezależnie.","explanation":"Zagrożenia pyłowe, cieplne, elektryczne i pożarowe wymagają odrębnych środków technicznych i organizacyjnych.","feedback":["Tak. Zagrożenia pyłowe, cieplne, elektryczne i pożarowe wymagają odrębnych środków technicznych i organizacyjnych.","Nie. Zagrożenia pyłowe, cieplne, elektryczne i pożarowe wymagają odrębnych środków technicznych i organizacyjnych.","Nie. Zagrożenia pyłowe, cieplne, elektryczne i pożarowe wymagają odrębnych środków technicznych i organizacyjnych.","Nie. Zagrożenia pyłowe, cieplne, elektryczne i pożarowe wymagają odrębnych środków technicznych i organizacyjnych."],"task":"Narysuj plan warsztatu z kołem, strefą mokrą, składowaniem suchych surowców, miejscem odpylania, piecem i drogą ewakuacji. Dla każdej strefy zapisz zagrożenie, środek kontroli i odpowiedzialną osobę. Nie podawaj uniwersalnego odstępu pieca bez znajomości jego modelu."}}'::jsonb),
('garncarz-tradycja',9,'10. Wady szkliwa: spękania (crazing) i odpryski (shivering)','{"module":3,"editorial_status":"review_needed","curriculum_revision":3,"lesson_kind":"technical_curriculum","sections":[{"heading":"Dwa objawy, inne mechanizmy","text":"Crazing to sieć drobnych spękań szkliwa często związana z jego zbyt dużym współczynnikiem rozszerzalności cieplnej względem czerepu. Shivering to odpryskiwanie fragmentów szkliwa z krawędzi, możliwe przy zbyt dużych naprężeniach ściskających. Te zjawiska nie są identyczne i wymagają innych kierunków korekty."},{"heading":"Zrozum zmianę wymiaru","text":"Podczas ogrzewania i chłodzenia masa ceramiczna oraz szkliwo rozszerzają się i kurczą. Ponieważ są połączone, różnica ich reakcji powoduje naprężenia. Problemu nie rozwiązuje zawsze ponowne ogrzanie tej samej sztuki; należy przetestować zgodność konkretnego układu i program technologiczny."},{"heading":"Dlaczego odprysk jest poważny","text":"Płatek szkliwa odrywający się od krawędzi naczynia może być ostry i trafić do żywności. Naczynia z takimi wadami nie należy dopuszczać do użytkowania spożywczego. Crazing również wymaga oceny, ponieważ nieprawidłowe dopasowanie może pogarszać trwałość i higienę."},{"heading":"Przykład rozpoznania","text":"Na kubku A widoczna jest gęsta siateczka cienkich pęknięć; na kubku B brakuje fragmentów szkliwa przy brzegu. W protokole zapisz osobno crazing dla A i shivering dla B, a następnie sprawdź materiały i wyniki próbek."},{"heading":"Ćwiczenie diagnozy","text":"Przygotuj rysunki powierzchni: siatka pęknięć i odprysk z krawędzi. Zestaw dla nich objaw, mechanizm prawdopodobny, dowód wymagający potwierdzenia, skutek i decyzję o wycofaniu wyrobu."}],"illustration":"garncarz-szkliwo","references":[{"label":"Źródło wiedzy technicznej","url":"https://www.digitalfire.com/glossary/glaze%2Bfit"}],"learning":{"intro":"Crazing to sieć drobnych spękań szkliwa często związana z jego zbyt dużym współczynnikiem rozszerzalności cieplnej względem czerepu. Shivering to odpryskiwanie fragmentów szkliwa z krawędzi, możliwe przy zbyt dużych naprężeniach ściskających. Te zjawiska nie są identyczne i wymagają innych kierunków korekty.","situation":"Na kubku A widoczna jest gęsta siateczka cienkich pęknięć; na kubku B brakuje fragmentów szkliwa przy brzegu. W protokole zapisz osobno crazing dla A i shivering dla B, a następnie sprawdź materiały i wyniki próbek.","question":"Na krawędzi kubka odrywają się drobne płatki szkliwa. Którą wadę należy rozważyć?","options":["Crazing, wyłącznie siateczka pęknięć bez odprysku.","Poprawne stopienie szkliwa potwierdzające trwałość.","Shivering — odpryski w wyniku niedopasowania termicznego szkliwa i masy.","Wyłącznie nierównomierne suszenie jeszcze mokrej gliny."],"correct":2,"example":"Shivering — odpryski w wyniku niedopasowania termicznego szkliwa i masy.","explanation":"Shivering może dawać ostre odpryski szkliwa na krawędziach i stanowić istotne ryzyko dla naczynia użytkowego.","feedback":["Nie. Shivering może dawać ostre odpryski szkliwa na krawędziach i stanowić istotne ryzyko dla naczynia użytkowego.","Nie. Shivering może dawać ostre odpryski szkliwa na krawędziach i stanowić istotne ryzyko dla naczynia użytkowego.","Tak. Shivering może dawać ostre odpryski szkliwa na krawędziach i stanowić istotne ryzyko dla naczynia użytkowego.","Nie. Shivering może dawać ostre odpryski szkliwa na krawędziach i stanowić istotne ryzyko dla naczynia użytkowego."],"task":"Przygotuj rysunki powierzchni: siatka pęknięć i odprysk z krawędzi. Zestaw dla nich objaw, mechanizm prawdopodobny, dowód wymagający potwierdzenia, skutek i decyzję o wycofaniu wyrobu."}}'::jsonb),
('garncarz-tradycja',10,'11. Naczynia użytkowe: nasiąkliwość, pęknięcia i kontrola jakości','{"module":3,"editorial_status":"review_needed","curriculum_revision":3,"lesson_kind":"technical_curriculum","sections":[{"heading":"Wygląd to tylko początek","text":"Gotowy produkt musi odpowiadać zadeklarowanemu przeznaczeniu. Miska ozdobna nie podlega tym samym wymaganiom co kubek do gorących napojów. Dla funkcji użytkowej liczy się prawidłowy wypał, odporność na normalne warunki, czystość, nieszkodliwość materiałów i zgodność z wymaganiami kontaktu z żywnością."},{"heading":"Co zapisuje kontrola","text":"Protokół powinien wskazywać masę ceramiczną, dostawcę, szkliwo, serię wypału, kontrolę wymiaru, pęknięcia, odpryski i decyzję o dopuszczeniu. Przy produkcji żywnościowej należy prowadzić stosowne testy i dokumenty zgodności. ''Nie zawiera ołowiu'' na jednym składniku nie oznacza automatycznie, że całe naczynie jest bezpieczne."},{"heading":"Prosty przykład pomiaru","text":"W partii 10 kubków projekt przewiduje wysokość 100±3 mm. Pomiar pierwszej sztuki wynosi 104 mm — przekracza dopuszczalny zakres 97–103 mm. Nie można uznać wymiaru za zgodny, nawet jeżeli szkliwo wygląda perfekcyjnie."},{"heading":"Kiedy wycofać wyrób","text":"Pęknięcie przez ściankę, odpryskujące szkliwo, ostre krawędzie lub niepotwierdzone bezpieczeństwo materiału są powodami do wstrzymania wydania zgodnie z ustalonymi kryteriami. Należy oddzielić naprawę kosmetyczną od wady mogącej naruszać bezpieczeństwo produktu."},{"heading":"Ćwiczenie odbiorowe","text":"Zbuduj protokół dla partii 10 naczyń z 10 kryteriami. Wprowadź trzy niezgodności: wymiar 104 mm zamiast dopuszczalnych 97–103 mm, odprysk szkliwa i brak karty zastosowanego szkliwa. Wskaż, które sztuki wymagają zatrzymania i jakich dowodów brakuje."}],"illustration":"garncarz-szkliwo","references":[{"label":"Źródło wiedzy technicznej","url":"https://www.digitalfire.com/glossary/glaze%2Bfit"}],"learning":{"intro":"Gotowy produkt musi odpowiadać zadeklarowanemu przeznaczeniu. Miska ozdobna nie podlega tym samym wymaganiom co kubek do gorących napojów. Dla funkcji użytkowej liczy się prawidłowy wypał, odporność na normalne warunki, czystość, nieszkodliwość materiałów i zgodność z wymaganiami kontaktu z żywnością.","situation":"Pęknięcie przez ściankę, odpryskujące szkliwo, ostre krawędzie lub niepotwierdzone bezpieczeństwo materiału są powodami do wstrzymania wydania zgodnie z ustalonymi kryteriami. Należy oddzielić naprawę kosmetyczną od wady mogącej naruszać bezpieczeństwo produktu.","question":"Projekt kubka zakłada 100 ±3 mm. Czy sztuka o wysokości 104 mm spełnia tolerancję wymiarową?","options":["Tak, ponieważ różnica 4 mm jest mniejsza niż 5%.","Tak, jeżeli kolor szkliwa jest zgodny.","Nie da się tego ocenić, bo tolerancja nie określa granic.","Nie: przedział dopuszczalny to 97–103 mm."],"correct":3,"example":"Nie: przedział dopuszczalny to 97–103 mm.","explanation":"100±3 mm oznacza granice 97 i 103 mm; 104 mm jest poza przedziałem.","feedback":["Nie. 100±3 mm oznacza granice 97 i 103 mm; 104 mm jest poza przedziałem.","Nie. 100±3 mm oznacza granice 97 i 103 mm; 104 mm jest poza przedziałem.","Nie. 100±3 mm oznacza granice 97 i 103 mm; 104 mm jest poza przedziałem.","Tak. 100±3 mm oznacza granice 97 i 103 mm; 104 mm jest poza przedziałem."],"task":"Zbuduj protokół dla partii 10 naczyń z 10 kryteriami. Wprowadź trzy niezgodności: wymiar 104 mm zamiast dopuszczalnych 97–103 mm, odprysk szkliwa i brak karty zastosowanego szkliwa. Wskaż, które sztuki wymagają zatrzymania i jakich dowodów brakuje."}}'::jsonb),
('garncarz-tradycja',11,'12. Projekt końcowy: od rysunku kubka do karty jakości','{"module":3,"editorial_status":"review_needed","curriculum_revision":3,"lesson_kind":"technical_curriculum","sections":[{"heading":"Zdefiniuj wymaganie","text":"Masz zaprojektować kubek o wysokości 100 mm i średnicy zewnętrznej 90 mm po wypale, z wygodną krawędzią i uchwytem. W ćwiczeniu przyjmij hipotetyczny skurcz liniowy 12%, ale przed realnym wykonaniem musisz odczytać zakres masy i przetestować próbkę. Wyrób docelowy ma spełniać wymagania dla zamierzonego kontaktu z żywnością."},{"heading":"Wymiary w stanie mokrym","text":"Dla obu wymiarów zastosuj formułę X_początkowy=X_końcowy/(1−0,12). Wysokość: 100/0,88≈113,6 mm; średnica: 90/0,88≈102,3 mm. Rzeczywisty projekt musi ponadto wskazywać grubość ściany, dno, mocowanie ucha i przyjętą metodę formowania."},{"heading":"Plan procesu i jakości","text":"W dokumencie rozdziel: przygotowanie masy, formowanie, łączenie ucha, suszenie, ocena przed biskwitem, pierwszy wypał, ewentualne szkliwienie, drugi wypał oraz odbiór. Dla każdego etapu wskaż ryzyko: pył, pęknięcie suszenia, niedosuszenie, niezgodność szkliwa lub wada użytkowa."},{"heading":"Scenariusz z wadą","text":"Po wypale kubek ma prawidłową wysokość, ale przy krawędzi odrywa się mały płatek szkliwa. Pomimo zgodnego wymiaru trzeba wyrób wycofać z użytkowania spożywczego i sprawdzić przyczynę w dopasowaniu szkliwa i masy. Kontrola wymiaru nie zastępuje kontroli bezpieczeństwa."},{"heading":"Praca końcowa","text":"Oddaj przekrój z dwoma wymiarami docelowymi, rachunek skurczu, kartę masy i szkliwa z polami na dokumentację, plan procesu oraz dziesięciopunktowy protokół odbioru. Odpowiedz pisemnie: co zrobiłbyś z kubkiem z odpryskiem i jak zmienisz proces w następnej próbie."}],"illustration":"garncarz-skurcz","references":[{"label":"Źródło wiedzy technicznej","url":"https://openlearning.aalto.fi/course/view.php?id=110&section=13"}],"learning":{"intro":"Masz zaprojektować kubek o wysokości 100 mm i średnicy zewnętrznej 90 mm po wypale, z wygodną krawędzią i uchwytem. W ćwiczeniu przyjmij hipotetyczny skurcz liniowy 12%, ale przed realnym wykonaniem musisz odczytać zakres masy i przetestować próbkę. Wyrób docelowy ma spełniać wymagania dla zamierzonego kontaktu z żywnością.","situation":"Po wypale kubek ma prawidłową wysokość, ale przy krawędzi odrywa się mały płatek szkliwa. Pomimo zgodnego wymiaru trzeba wyrób wycofać z użytkowania spożywczego i sprawdzić przyczynę w dopasowaniu szkliwa i masy. Kontrola wymiaru nie zastępuje kontroli bezpieczeństwa.","question":"W zadaniu skurcz przyjęto jako 12%; jaka średnica początkowa daje teoretycznie 90 mm po wypale?","options":["79,2 mm.","Około 102,3 mm.","90 mm, bo skurcz dotyczy wyłącznie wysokości.","112 mm dokładnie, niezależnie od danych."],"correct":1,"example":"Około 102,3 mm.","explanation":"90/0,88 ≈ 102,27 mm; model dotyczy obu wymiarów liniowych, ale musi być zweryfikowany próbą.","feedback":["Nie. 90/0,88 ≈ 102,27 mm; model dotyczy obu wymiarów liniowych, ale musi być zweryfikowany próbą.","Tak. 90/0,88 ≈ 102,27 mm; model dotyczy obu wymiarów liniowych, ale musi być zweryfikowany próbą.","Nie. 90/0,88 ≈ 102,27 mm; model dotyczy obu wymiarów liniowych, ale musi być zweryfikowany próbą.","Nie. 90/0,88 ≈ 102,27 mm; model dotyczy obu wymiarów liniowych, ale musi być zweryfikowany próbą."],"task":"Oddaj przekrój z dwoma wymiarami docelowymi, rachunek skurczu, kartę masy i szkliwa z polami na dokumentację, plan procesu oraz dziesięciopunktowy protokół odbioru. Odpowiedz pisemnie: co zrobiłbyś z kubkiem z odpryskiem i jak zmienisz proces w następnej próbie."}}'::jsonb)
on conflict(course_slug,lesson_no) do update set title_pl=excluded.title_pl,
material=public.ta_lessons.material||excluded.material,updated_at=now();
update public.ta_courses set description_pl='12 lekcji garncarstwa od podstaw: rodzaje mas, glina i szamot, narzędzia i koło, projekt kubka z obliczeniem skurczu, formowanie, suszenie, biskwit, szkliwo i angoba, bezpieczna praca z piecem i pyłem, wady szkliwa, kontrola jakości oraz projekt końcowy. Kurs edukacyjny, wymaga praktyki pod okiem doświadczonego ceramika i nie nadaje uprawnień zawodowych.' where slug='garncarz-tradycja';
update public.ta_course_previews set
curiosity='Dlaczego gliniany kubek maleje podczas suszenia i wypału — oraz kiedy szkliwo może stać się niebezpieczne?',
scenario='Projektujesz kubek 100 mm wysokości po wypale. Zakładasz skurcz 12%, liczysz wymiary początkowe i oceniasz późniejsze pęknięcia oraz zgodność szkliwa.',
outcome_1='Poznasz rodzaje mas ceramicznych, plastyczność, szamot i narzędzia garncarskie.',
outcome_2='Obliczysz skurcz, wybierzesz metodę formowania i rozpoznasz błędy suszenia oraz wypału.',
outcome_3='Przygotujesz rysunek, kartę materiału i protokół jakości naczynia, rozpoznając ryzyka dla użytkownika.',
source_url='https://openlearning.aalto.fi/course/view.php?id=110&section=13',
module_titles='["1. Materiały, koło i projekt (1–4)","2. Formowanie, suszenie, pierwszy wypał, szkliwo (5–8)","3. Bezpieczeństwo, wady, jakość, projekt końcowy (9–12)"]'::jsonb,
review_status='review_needed',
editorial_note='12 lekcji o podstawach ceramiki, z obliczeniami, ćwiczeniami i źródłami technicznymi. Wymaga praktycznej recenzji przez garncarza, sprawdzenia zasad kontaktu z żywnością i testu zalogowanego ucznia. Nie upoważnia do samodzielnej obsługi pieca.'
where course_slug='garncarz-tradycja';
COMMIT;
